    int* block2 = allocator.allocate(200);
    int* block3 = allocator.allocate(300);

    std::cout << "Allocated 3 blocks with values: " << *block1 << ", " << *block2 << ", " << *block3 << std::endl;

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "  Active count: " << allocator.active_count << std::endl;
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
#endif

    // Demonstrate push() behavior through deallocate()
    std::cout << "\n--- Phase 2: Deallocating block2 (internally calls push()) ---" << std::endl;
    allocator.deallocate(block2);

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "  Active count: " << allocator.active_count << std::endl;
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
#endif

    // Demonstrate LIFO behavior (most recently pushed block is popped first)
    std::cout << "\n--- Phase 3: Allocating again (demonstrates LIFO) ---" << std::endl;
    int* block4 = allocator.allocate(400);
    std::cout << "New allocation gets the most recently freed block (LIFO)" << std::endl;
    std::cout << "  Block4 address: " << static_cast<void*>(block4) << std::endl;
    std::cout << "  Block2 address: " << static_cast<void*>(block2) << std::endl;
    std::cout << "  Same address? " << (block4 == block2 ? "Yes - LIFO verified!" : "No") << std::endl;

    // Clean up remaining allocations
    std::cout << "\n--- Phase 4: Cleanup (push back to free list) ---" << std::endl;
    allocator.deallocate(block1);
    allocator.deallocate(block3);
    allocator.deallocate(block4);

#ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "Final state (all blocks returned to free list):" << std::endl;
    std::cout << "  Active count: " << allocator.active_count << std::endl;
    std::cout << "  Total allocations: " << allocator.total_allocs << std::endl;
    std::cout << "  Total deallocations: " << allocator.total_deallocs << std::endl;
#endif

    std::cout << "\n=== Free List Behavior Summary ===" << std::endl;
    std::cout << "The free list is managed as a LIFO (stack) structure:" << std::endl;
    std::cout << "- push(block): Adds block to the head of free list" << std::endl;
    std::cout << "- pop(): Removes and returns the head block from free list" << std::endl;
    std::cout << "- allocate() internally calls pop() to get a free block" << std::endl;
    std::cout << "- deallocate() internally calls push() to return a block" << std::endl;
    std::cout << "- Most recently deallocated block is the next to be allocated" << std::endl;
