	 * 
	 * @return The file handle.
	 */
	const FILE* handle() const {
		return file_;
	}

	/** 
	 * @return True if an error has occurred during file operations.
	 */
	bool error() const {
		return error_;
	}

	/** 
	 * @return True if no error has occurred during file operations.
	 */
	operator bool() const {
		return !error();
	}
