Here's the complete implementation:

```cpp
#include <hexi/shared.h>
#include <hexi/pmc/buffer_adaptor.h>
#include <hexi/pmc/binary_stream_writer.h>
#include <hexi/pmc/binary_stream_reader.h>
#include <vector>
#include <cstdint>

using namespace hexi::detail;

template<typename T>
std::size_t encode_varint(hexi::pmc::binary_stream_writer& writer, T value) {
    std::size_t bytes_written = 0;

    // Convert to unsigned for proper bit manipulation
    using unsigned_type = std::make_unsigned_t<T>;
    unsigned_type uvalue = static_cast<unsigned_type>(value);

    do {
        std::uint8_t byte = uvalue & 0x7F; // Take lower 7 bits
        uvalue >>= 7; // Shift right by 7 bits

        if (uvalue != 0) {
            byte |= 0x80; // Set continuation bit if more bytes follow
        }

        writer << byte;
        bytes_written++;
    } while (uvalue != 0);

    return bytes_written;
}

template<typename T>
T decode_varint(hexi::pmc::binary_stream_reader& reader) {
    using unsigned_type = std::make_unsigned_t<T>;
    unsigned_type result = 0;
    int shift = 0;

    while (true) {
        std::uint8_t byte;
        reader >> byte;

        // Check if reader is in error state
        if (!reader.good()) {
            return static_cast<T>(0);
        }

        // Add the lower 7 bits to result
        result |= static_cast<unsigned_type>(byte & 0x7F) << shift;

        // If MSB is not set, we're done
        if ((byte & 0x80) == 0) {
            break;
        }

        shift += 7;
    }

    return static_cast<T>(result);
}

template<typename T>
bool encode_decode_roundtrip(T original_value) {
    // Create a buffer for the encoded data
    std::vector<std::byte> buffer;

    // Create buffer adaptor with init_empty
    hexi::pmc::buffer_adaptor<std::vector<std::byte>> adaptor(buffer, init_empty);

    // Create writer and encode the value
    hexi::pmc::binary_stream_writer writer(adaptor);
    encode_varint(writer, original_value);

    // Create reader and decode the value
    hexi::pmc::binary_stream_reader reader(adaptor);
    T decoded_value = decode_varint<T>(reader);

    // Compare and return result
    return original_value == decoded_value;
}
