		const auto min_req_size = write_ + length;

		if(buffer_.size() < min_req_size) [[likely]] {
			if constexpr(has_resize_overwrite<buf_type>) {
				buffer_.resize_and_overwrite(min_req_size, [](char*, size_type size) {
